head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getVisibleColData]<br/>필터링, 정렬 상태를 기준으로 Display 포맷이 적용되지 않은 특정 Column 의 데이터를 1차원 배열로 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 데이터를 조회할 Column 의 ID 를 설정해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="columnInfo 파라미터에 Column ID(name / amount / dept / calc)를 설정하여 해당 Column 의 데이터를 1차원 배열로 조회합니다."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - amount : number, Row2 는 null (null -> '' 검증)
    // - etc : GridView Column 과 바인딩되지 않는 컬럼
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="etc" name="etc" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John",  "amount": 23456, "dept": "Sales", "etc": "etc1" },
        { "name": "Jane",  "amount": 12000, "dept": "Dev",   "etc": "etc2" },
        { "name": "Mike",  "amount": null,  "dept": "Sales", "etc": "etc3" },
        { "name": "Amy",   "amount": 8500,  "dept": "Dev",   "etc": "etc4" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 - name / amount(displayFormat) / dept / calc(expression))
    // calc : inputType="expression" - amount*2 계산 (@spec 검증용)
    // 마지막 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getVisibleColData 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="금액"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol3" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="계산(amount*2)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // amount : number + displayFormat (원본 23456 -> 표시 "23,456")
    strTarget += '<w2:column width="120" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    // calc : inputType="expression" - amount 의 2배 (@spec 계산값 검증)
    strTarget += '<w2:column width="*" style="" inputType="expression" dataType="number" id="calc" expression="Number(display(\'amount\'))*2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getVisibleColData 확인 : par_columnInfo 의 Column ID 로 호출 -> 해당 Column 데이터를 1차원 배열로 반환
scwin.btn_getVisibleColData_onclick = function () {
    let colId = par_columnInfo.getValue();
    let rtn = target1.getVisibleColData(colId);
    wf_body_bottom.getObj("scwin").setReturnValue("getVisibleColData('" + colId + "') : " + JSON.stringify(rtn));
}
